// Keep measured customer-facing field labels in Portuguese without changing quoted names or order details.
function customerReplyText(value) {
  return String(value ?? '').replace(/(^|\n)([ \t]*(?:[-*][ \t]+)?(?:\*\*)?Produto)\s*\/\s*Flavors(?=\s*:)/gi, '$1$2 e sabores');
}
// Multiple flavors require explicit allocations; the extractor writes "Flavor: units" in the product field.
function flavorAllocationValid(type, quantity) {
  const text=String(type ?? '');
  const multiple=/\s(?:e|ou)\s|[+;,]/i.test(text) || (text.match(/:\s*\d+/g)||[]).length>1;
  if (!multiple) return true;
  const allocations=[...text.matchAll(/:\s*(\d+)/g)].map(m=>Number(m[1]));
  const total=Number(String(quantity ?? '').match(/\d+/)?.[0] ?? 0);
  return allocations.length>=2 && allocations.every(n=>n>0) && allocations.reduce((a,b)=>a+b,0)===total;
}

// Takes the fields the extractor (Chain) pulled out of the chat and injects the agent's reply.
// Anti-invention guard: a lead only reaches the baker when every field is real, so a phantom
// opportunity built out of placeholders never gets registered. Proven offline in
// tests/run-lead-guard.js against the agent's real hallucinated outputs.
function guard(o){
  o = o || {};
  const s = v => String(v==null?'':v).trim();
  const isPlaceholderContact = v => /(exemplo|example|teste|test|dominio|seuemail|nome)\b/i.test(v) || /@(exemplo|example|teste|test)\./i.test(v) || /^(cliente|contato)@/i.test(v);
  const looksEmail = v => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v);
  const looksPhoneBR = v => { const d=(v.match(/\d/g)||[]).length; return d>=10 && d<=13; };
  const isRealContact = v => { v=s(v); return !!v && !isPlaceholderContact(v) && (looksEmail(v)||looksPhoneBR(v)); };
  const VAGUE = ['','a confirmar','a definir','não informado','nao informado','variada','variado','grande','pequeno','n/a','sem tema','a combinar'];
  const isVague = v => VAGUE.includes(s(v).toLowerCase());
  const isGenericName = v => { v=s(v).toLowerCase(); return !v || /^(cliente|festa|anivers|doce aurora|docinhos artesanais)/.test(v); };
  const isInventedAbsDate = v => { const m=s(v).match(/^(\d{4})-\d{2}-\d{2}/); return !!m && (+m[1] < 2026); };
  const r=[];
  // Calcula a completude pelos sete campos reais; o booleano ready da IA não é fonte de verdade.
  if(isGenericName(o.nome)) r.push('nome ausente/genérico');
  if(!isRealContact(o.contato)) r.push('contato ausente/placeholder');
  if(isVague(o.tipo)) r.push('tipo vago');
  // Block kitchen requests until the customer has allocated every selected flavor.
  if(!flavorAllocationValid(o.tipo, o.quantidade)) r.push('divisao entre sabores ausente/invalida');
  if(isVague(o.quantidade)) r.push('quantidade vaga');
  if(!s(o.data)||isInventedAbsDate(o.data)) r.push('data ausente/inventada');
  if(isVague(o.tema)) r.push('tema vago');
  if(isVague(o.retirada)) r.push('retirada/entrega vaga');
  return { canRegister: r.length===0, blockReason: r.join('; ') };
}
// Unwraps a reply the agent sometimes returns as a JSON STRING (chat-history contamination).
// Proven offline in tests/run-reply-unwrap.js (raw-JSON bug seen in execution 3801).
function unwrapReply(v){
  let cur = v;
  for (let i=0;i<4;i++){
    if (cur==null) return '';
    if (typeof cur==='object'){
      if (cur.output && cur.output.reply!==undefined){ cur=cur.output.reply; continue; }
      if (cur.reply!==undefined){ cur=cur.reply; continue; }
      return '';
    }
    const str=String(cur).trim();
    if (str.charCodeAt(0) === 123){ try { cur=JSON.parse(str); continue; } catch(e){ return str; } }
    return str;
  }
  return typeof cur==='string'?cur:'';
}
let agentReply = '';
try { agentReply = unwrapReply($('Doce Aurora Agent').first().json.output); } catch(e) { agentReply = ''; }
// Apply the customer-language correction before the reply reaches the website.
agentReply = customerReplyText(agentReply);
for (const item of $input.all()) {
  const fields = item.json.output || {};
  const g = guard(fields);
  item.json.output = Object.assign({}, fields, { reply: agentReply, ready: g.canRegister, canRegister: g.canRegister, blockReason: g.blockReason });
}
return $input.all();
